div><div class="grid" style="margin-top:18px"><div class="card c6"><h2>Información de obra</h2><p><b>Cliente:</b> <?=et($p['business_name'])?><br><b>Ubicación:</b> <?=et(trim(($p['city']??'').' '.($p['province']??'')))?><br><b>Arquitecto / constructora:</b> <?=et($p['partner_name']?:'—')?><br><b>Responsable técnico:</b> <?=et($p['manager_name']?:'Sin asignar')?></p></div><div class="card c6"><h2>Equipo técnico</h2><?php if($teamRows):?><ul><?php foreach($teamRows as $u):?><li><?=et($u['name'])?></li><?php endforeach;?></ul><?php else:?><p class="muted">Todavía no hay técnicos asignados.</p><?php endif;?></div></div>
<?php if(tCanManage()):?><div class="card"><h2>Administrar proyecto técnico</h2><form method="post" action="?a=save_technical_project"><input type="hidden" name="project_id" value="<?=$id?>"><div class="grid"><div class="c6"><label><b>Estado técnico</b></label><select name="technical_status"><?php foreach($statuses as $k=>$v):?><option value="<?=et($k)?>" <?=$p['technical_status']===$k?'selected':''?>><?=et($v)?></option><?php endforeach;?></select></div><div class="c6"><label><b>Project Manager / responsable</b></label><select name="manager_user_id"><option value="">Sin asignar</option><?php foreach($users as $u):?><option value="<?=$u['id']?>" <?=(int)$p['technical_manager_user_id']===(int)$u['id']?'selected':''?>><?=et($u['name'])?><?=!empty($u['area'])?' · '.et($u['area']):''?></option><?php endforeach;?></select></div></div><h3>Técnicos asignados</h3><div class="checks"><?php $selected=array_map(fn($x)=>(int)$x['id'],$teamRows);foreach($users as $u):?><label class="check"><input type="checkbox" name="technical_users[]" value="<?=$u['id']?>" <?=in_array((int)$u['id'],$selected,true)?'checked':''?>> <?=et($u['name'])?><?=!empty($u['area'])?' · '.et($u['area']):''?></label><?php endforeach;?></div><p><button class="btn" type="submit">Guardar asignación</button></p></form></div><?php endif;?>
<div class="card"><div style="display:flex;align-items:center;gap:10px"><h2 style="flex:1">Equipamiento vendido</h2><?php if($quote):?><a class="btn light" href="?a=technical_quote&id=<?=$quote['id']?>">Ver detalle / PDF técnico</a><?php endif;?></div><?php if(!$quote):?><p class="muted">Este proyecto todavía no tiene presupuesto.</p><?php else:?><table><thead><tr><th>Imagen</th><th>SKU</th><th>Descripción</th><th>Cantidad</th></tr></thead><tbody><?php $last=null;foreach($items as $it):$sec=$it['section_title']?:'Materiales';if($sec!==$last):$last=$sec;?><tr class="section"><td colspan="4"><?=et($sec)?></td></tr><?php endif;?><tr><td class="pic"><?php if(!empty($it['image_data'])&&!empty($it['image_mime'])):?><img src="data:<?=et($it['image_mime'])?>;base64,<?=base64_encode($it['image_data'])?>"><?php endif;?></td><td><b><?=et($it['sku'])?></b></td><td><?=et($it['description'])?></td><td><?=et(rtrim(rtrim(number_format((float)$it['quantity'],2,'.',''),'0'),'.'))?></td></tr><?php endforeach;?><?php foreach($labor as $l):?><tr class="section"><td colspan="4"><?=et($l['title'])?></td></tr><tr><td></td><td colspan="3"><?=et($l['description'])?></td></tr><?php endforeach;?></tbody></table><?php endif;?></div></main></body></html>